#include <stdio.h>
#include <stdint.h>
#include <string.h>

uint64_t largest_product_in_series(const char * series, uint64_t series_length)
{
    uint64_t largest = 0;
    for (size_t i = 0; i < strlen(series) - series_length; i++) {
        uint64_t test_number = series[i] - '0';
        printf("%c ", series[i]);
        for (uint64_t j = i + 1; j < i + series_length; j++) {
            printf("%c ", series[j]);
            test_number *= (series[j] - '0');
        }
        printf("\n");
    largest = (test_number > largest) ? test_number: largest;
    }

    return largest;

}

int main(void)
{
    char series[] = "";

    uint64_t largest = 0;

    // test with example
    largest = largest_product_in_series(series, 4);
    printf("%ld\n", largest);

    // Actual run
    largest = largest_product_in_series(series, 13);
    printf("%ld\n", largest);

    return 0;
}